def is_prime(n):
    """Return True if n is a prime number, otherwise False.

    This function checks divisibility from 2 up to the square root of n.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# This algorithm uses 6k ± 1 optimization to reduce the number of divisibility tests.

